329	// genExpr generates IR for an expression and returns the operand
330	func (g *Generator) genExpr(node *ast.Node) (Operand, error) {
331		if node == nil {
332			return Operand{}, fmt.Errorf("nil expression")
333		}
334	
335		switch node.Kind {
336		case ast.NodeIntLit:
337			// Parse integer literal
338			var val int64
339			fmt.Sscanf(node.Value, "%d", &val)
340			return Operand{IsImm: true, ImmVal: val}, nil
341	
342		case ast.NodeIdent:
343			return Operand{Name: node.Value}, nil
344	
345		case ast.NodeBinaryExpr:
346			return g.genBinaryExpr(node)
347	
348		case ast.NodeCallExpr:
349			return g.genCallExpr(node)
350	
351		default:
352			return Operand{}, fmt.Errorf("unsupported expression kind: %d", node.Kind)
353		}
354	}
355	
356	// genBinaryExpr generates IR for a binary expression
357	func (g *Generator) genBinaryExpr(node *ast.Node) (Operand, error) {
358		if len(node.Children) < 2 {
359			return Operand{}, fmt.Errorf("binary expression requires 2 operands")
360		}
361	
362		left, err := g.genExpr(node.Children[0])
363		if err != nil {
364			return Operand{}, err
365		}
366	
367		right, err := g.genExpr(node.Children[1])
368		if err != nil {
369			return Operand{}, err
370		}
371	
372		result := g.newTemp()
373		op := g.opcodeFromOp(node.Value)
374	
375		g.emit(Instruction{
376			Op:   op,
377			Dest: result,
378			Src1: left,
379			Src2: right,
380		})
381	
382		return result, nil
383	}
384	
385	// genCallExpr generates IR for a function call
386	func (g *Generator) genCallExpr(node *ast.Node) (Operand, error) {
387		if len(node.Children) == 0 {
388			return Operand{}, fmt.Errorf("call expression requires function name")
389		}
390	
391		fnName := node.Children[0].Value
392	
393		// Emit parameters
394		for i := 1; i < len(node.Children); i++ {
395			argOp, err := g.genExpr(node.Children[i])
396			if err != nil {
397				return Operand{}, err
398			}
399			g.emit(Instruction{
400				Op:   OpParam,
401				Src1: argOp,
402			})
403		}
404	
405		// Emit call
406		result := g.newTemp()
407		g.emit(Instruction{
408			Op:   OpCall,
409			Dest: result,
410			Fn:   fnName,
411		})
412	
413		return result, nil
414	}
