433	func (g *Generator) emit(instr Instruction) {
434		if g.currentFn != nil {
435			g.currentFn.Body = append(g.currentFn.Body, instr)
436		} else {
437			g.program.Main = append(g.program.Main, instr)
438		}
439	}
