441	func (g *Generator) opcodeFromOp(op string) Opcode {
442		switch op {
443		case "+":
444			return OpAdd
445		case "-":
446			return OpSub
447		case "*":
448			return OpMul
449		case "/":
450			return OpDiv
451		case "==":
452			return OpEq
453		case "!=":
454			return OpNe
455		case "<":
456			return OpLt
457		case ">":
458			return OpGt
459		case "<=":
460			return OpLe
461		case ">=":
462			return OpGe
463		default:
464			return OpNoop
465		}
466	}
