468	// genStructDecl generates IR for a struct declaration
469	func (g *Generator) genStructDecl(node *ast.Node) error {
470		if node.Value == "" {
471			return fmt.Errorf("struct declaration must have a name")
472		}
473	
474		name := node.Value
475		fields := []string{}
476	
477		// Extract field names from children
478		for _, field := range node.Children {
479			if field.Kind == ast.NodeFieldDecl {
480				fields = append(fields, field.Value)
481			}
482		}
483	
484		// Store struct definition
485		g.structFields[name] = fields
486	
487		// Calculate struct size (8 bytes per field)
488		size := len(fields) * 8
489	
490		// Save current function context
491		prevFn := g.currentFn
492		g.currentFn = nil // Emit to Main context
493	
494		// Emit OpStructDef instruction
495		g.emit(Instruction{
496			Op:   OpStructDef,
497			Fn:   name,
498			Src1: Operand{IsImm: true, ImmVal: int64(size)},
499		})
500	
501		// Restore function context
502		g.currentFn = prevFn
503	
504		return nil
505	}
